const body = $input.first().json.body;
const title = body.title || '台灣旅遊';
const itinerary = body.itinerary || [];

// Build structured description
const dayDescriptions = itinerary.map(day => {
  const morning   = (day.morning   || []).join('、') || '–';
  const afternoon = (day.afternoon || []).join('、') || '–';
  const evening   = (day.evening   || []).join('、') || '–';
  return `Day ${day.day}: morning(${morning}), afternoon(${afternoon}), evening(${evening})`;
}).join(' | ');

// Collect all spots for visual reference
const allSpots = itinerary.flatMap(day => [
  ...(day.morning || []),
  ...(day.afternoon || []),
  ...(day.evening || [])
]).slice(0, 8).join(', ');

const totalDays = itinerary.length;

const prompt = `A cute kawaii-style travel itinerary illustration card for "${title}". Layout: ${totalDays} vertical day columns side by side, each column divided into 3 rows (morning 早上 / afternoon 下午 / evening 晚上) with a small row label. Each cell contains a tiny kawaii illustration of the location. Places: ${dayDescriptions}. Overall featured spots: ${allSpots}. Style: pastel pink and mint color scheme, Japanese travel poster aesthetic, soft watercolor texture, clean white background, Chinese day labels (第一天, 第二天...) as column headers, time labels in small Chinese text, no large text blocks, highly detailed kawaii icons, charming and cheerful mood.`;

return [{
  json: {
    model: 'gpt-image-1',
    prompt: prompt,
    n: 1,
    size: '1024x1024'
  }
}];

const item = $input.first().json;
const data = item.data;
if (data && data.length > 0 && data[0].b64_json) {
  const imageUrl = `data:image/png;base64,${data[0].b64_json}`;
  return [{ json: { image_url: imageUrl } }];
}
if (data && data.length > 0 && data[0].url) {
  return [{ json: { image_url: data[0].url } }];
}
throw new Error('No image data returned');
